#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard keyboard;
constexpr int BUTTON_PIN = 4;
bool previous = HIGH;

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  keyboard.begin();
  USB.begin();
}

void loop() {
  const bool pressed = digitalRead(BUTTON_PIN) == LOW;
  if (pressed && previous == HIGH) {
    keyboard.write('a');  // Test in a text editor on your own computer.
  }
  previous = pressed;
  delay(25);
}
